/**
 * November 2026 content calendar (owner: Bondu), imported from the Google Sheet
 * "Ferrn Content Calendar – November 2026 (X, Instagram, TikTok)" and expanded to
 * 3 posts a day (one X, one Instagram, one TikTok), Mon 2 – Mon 30 Nov: 87 posts.
 * Times are UTC: X 09:00, Instagram 12:00, TikTok 18:00 Lagos time.
 * Studio → Content → "Import November calendar" loads these as approved posts.
 */
type P = { platform: 'x' | 'instagram' | 'tiktok'; scheduled_at: string; format: string; theme: string; goal: string; audience: string; title: string; body: string; hashtags: string };

const at = (day: number, platform: P['platform']) =>
  `2026-11-${String(day).padStart(2, '0')}T${platform === 'x' ? '08' : platform === 'instagram' ? '11' : '17'}:00:00Z`;

const row = (day: number, platform: P['platform'], format: string, theme: string, goal: string, audience: string, title: string, body: string, hashtags: string): P =>
  ({ platform, scheduled_at: at(day, platform), format, theme, goal, audience, title, body, hashtags });

